/**
 * Tokenizer module for converting various input types to standardized string tokens.
 *
 * This module demonstrates Scala's type system with:
 * - Variance annotations (covariant/contravariant)
 * - Sealed trait hierarchies for exhaustive pattern matching
 * - Type classes for structural typing
 * - Option/Either for safe error handling
 * - Higher-kinded type simulation via functors and monads
 */

import java.time.{LocalDate, LocalDateTime}
import java.time.format.DateTimeFormatter
import scala.collection.mutable

// ============================================================================
// Type Classes (Scala equivalent of Python's Protocol / structural typing)
// ============================================================================

/** Type class for objects that can be converted to a token string. */
trait Tokenizable[A] {
  def toToken(a: A): String
}

/** Type class for objects with a measurable length. */
trait HasLength[A] {
  def length(a: A): Int
}

/** Contravariant processor that consumes tokens. */
trait TokenProcessor[-A] {
  def process(item: A): Unit
}

// ============================================================================
// Enums and Constants
// ============================================================================

sealed trait TokenType {
  def value: String
}

object TokenType {
  case object String extends TokenType { val value = "string" }
  case object Numeric extends TokenType { val value = "numeric" }
  case object Temporal extends TokenType { val value = "temporal" }
  case object Structured extends TokenType { val value = "structured" }
  case object Binary extends TokenType { val value = "binary" }
  case object Null extends TokenType { val value = "null" }
}

// ============================================================================
// Core Token Classes
// ============================================================================

/** Immutable token representation. */
case class Token(
  value: String,
  tokenType: TokenType,
  metadata: Map[String, Any] = Map.empty
) {

  /** Return new token with additional metadata. */
  def withMetadata(entries: (String, Any)*): Token =
    copy(metadata = metadata ++ entries.toMap)
}

/** Mutable batch of tokens — contrast with immutable Token. */
class MutableTokenBatch {
  private val _tokens = mutable.ListBuffer.empty[Token]
  private var _processed = false

  def add(token: Token): Unit = {
    if (_processed) throw new RuntimeException("Batch already processed")
    _tokens += token
  }

  def tokens: List[Token] = _tokens.toList

  def markProcessed(): Unit = { _processed = true }
}

// ============================================================================
// Generic Container Classes
// ============================================================================

/** Covariant container — can return subtypes. */
class TokenContainer[+A](items: Seq[A]) {
  private val _items: Vector[A] = items.toVector

  def getAll: Vector[A] = _items

  def mapTokens(f: A => String): List[String] = _items.map(f).toList
}

/** Contravariant sink — can accept supertypes. */
class TokenSink[-A] {
  private val _received = mutable.ListBuffer.empty[Any]

  def receive(item: A): Unit = _received += item

  def drain(): List[Any] = {
    val result = _received.toList
    _received.clear()
    result
  }
}

/** Invariant handler — exact type matching required. */
class BivariantHandler[A](private var _value: A) {
  def get: A = _value

  def set(value: A): Unit = { _value = value }

  def transform(f: A => A): A = {
    _value = f(_value)
    _value
  }
}

// ============================================================================
// Tokenizer Implementations
// ============================================================================

/** Abstract base tokenizer with generic input type. */
trait BaseTokenizer[T] {
  def tokenize(value: T): Token

  /** Lazy tokenization of multiple values. */
  def tokenizeBatch(values: Iterable[T]): Iterator[Token] =
    values.iterator.map(tokenize)
}

/** Tokenizer for string and byte-array types. */
class StringTokenizer(
  encoding: String = "UTF-8",
  normalizer: String => String = identity
) extends BaseTokenizer[Either[Array[Byte], String]] {

  override def tokenize(value: Either[Array[Byte], String]): Token = {
    val strValue = value match {
      case Left(bytes) => new String(bytes, encoding)
      case Right(str)  => str
    }
    Token(normalizer(strValue), TokenType.String)
  }

  /** Convenience method to tokenize a plain string. */
  def tokenize(value: String): Token =
    tokenize(Right(value))

  /** Convenience method to tokenize raw bytes. */
  def tokenize(value: Array[Byte]): Token =
    tokenize(Left(value))
}

/** Tokenizer for numeric types with precision handling. */
class NumericTokenizer(
  precision: Int = 6,
  formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[Any] {

  override def tokenize(value: Any): Token = value match {
    case bd: BigDecimal =>
      Token(
        s"%.${precision}f".format(bd.bigDecimal),
        TokenType.Numeric,
        Map("original_type" -> "Decimal")
      )
    case d: Double =>
      Token(
        s"%.${precision}f".format(d),
        TokenType.Numeric,
        Map("original_type" -> "float")
      )
    case f: Float =>
      Token(
        s"%.${precision}f".format(f.toDouble),
        TokenType.Numeric,
        Map("original_type" -> "float")
      )
    case i: Int =>
      Token(i.toString, TokenType.Numeric, Map("original_type" -> "int"))
    case l: Long =>
      Token(l.toString, TokenType.Numeric, Map("original_type" -> "int"))
    case other =>
      Token(other.toString, TokenType.Numeric, Map("original_type" -> other.getClass.getSimpleName))
  }
}

/** Tokenizer for date/time types. */
class TemporalTokenizer(formatStr: Option[String] = None)
  extends BaseTokenizer[Either[LocalDate, LocalDateTime]] {

  private val IsoFormat = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
  private val DateFormat = DateTimeFormatter.ofPattern("yyyy-MM-dd")

  override def tokenize(value: Either[LocalDate, LocalDateTime]): Token = {
    val fmt = formatStr.map(DateTimeFormatter.ofPattern).getOrElse {
      value match {
        case Right(_) => IsoFormat
        case Left(_)  => DateFormat
      }
    }

    val formatted = value match {
      case Right(dt)  => dt.format(fmt)
      case Left(date) => date.format(fmt)
    }

    Token(formatted, TokenType.Temporal)
  }

  /** Convenience method to tokenize a LocalDateTime. */
  def tokenize(value: LocalDateTime): Token =
    tokenize(Right(value))

  /** Convenience method to tokenize a LocalDate. */
  def tokenize(value: LocalDate): Token =
    tokenize(Left(value))
}

// ============================================================================
// Advanced: Union Types via Pattern Matching
// ============================================================================

/** Tokenizer that handles multiple types with pattern-matched dispatch. */
class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  /** Dispatch to appropriate tokenizer based on runtime type. */
  def tokenize(value: Any): Token = value match {
    case null             => Token("NULL", TokenType.Null)
    case s: String        => stringTokenizer.tokenize(s)
    case b: Array[Byte]   => stringTokenizer.tokenize(b)
    case i: Int           => numericTokenizer.tokenize(i)
    case l: Long          => numericTokenizer.tokenize(l)
    case f: Float         => numericTokenizer.tokenize(f)
    case d: Double        => numericTokenizer.tokenize(d)
    case bd: BigDecimal   => numericTokenizer.tokenize(bd)
    case dt: LocalDateTime => temporalTokenizer.tokenize(dt)
    case d: LocalDate     => temporalTokenizer.tokenize(d)
    case other            => Token(other.toString, TokenType.String, Map("fallback" -> true))
  }

  /** Tokenize with type-class-based dispatch for Tokenizable types. */
  def tokenize[A](value: A)(implicit ev: Tokenizable[A]): Token =
    Token(ev.toToken(value), TokenType.Structured)
}

// ============================================================================
// Complex Nested Generics
// ============================================================================

/**
 * Registry with complex nested generic types.
 *
 * Mixes mutable internal state with immutable external interfaces.
 */
class TokenRegistry[T] {
  private val _registry = mutable.Map.empty[String, TokenContainer[T]]
  private val _handlers = mutable.ListBuffer.empty[T => Option[Token]]

  def register(key: String, container: TokenContainer[T]): Unit =
    _registry(key) = container

  def addHandler(handler: T => Option[Token]): Unit =
    _handlers += handler

  /** Process all items in a container through all handlers. */
  def process(key: String): List[Option[Token]] = {
    _registry.get(key) match {
      case None => Nil
      case Some(container) =>
        container.getAll.map { item =>
          _handlers.iterator
            .map(handler => handler(item))
            .collectFirst { case some @ Some(_) => some }
            .flatten
        }.toList
    }
  }
}

// ============================================================================
// Higher-Kinded Type Simulation
// ============================================================================

/** Functor for tokens. */
class TokenFunctor[A](protected val _value: A) {
  def map[B](f: A => B): TokenFunctor[B] = new TokenFunctor(f(_value))

  def flatMap[B](f: A => TokenFunctor[B]): TokenFunctor[B] = f(_value)

  def getOrElse(default: => A): A =
    if (_value != null) _value else default
}

/** Extended monad operations. */
class TokenMonad[A](value: A) extends TokenFunctor[A](value) {
  /** Applicative apply. */
  def ap[B](funcWrapped: TokenMonad[A => B]): TokenMonad[B] =
    new TokenMonad(funcWrapped._value(_value))
}

object TokenMonad {
  def pure[A](value: A): TokenMonad[A] = new TokenMonad(value)
}

// ============================================================================
// JSON Structure Tokenization
// ============================================================================

/**
 * Tokenizer for JSON structures with recursive types.
 *
 * Uses Any to model the recursive JSON value type, with pattern matching
 * for type-safe access.
 */
class JsonTokenizer(pretty: Boolean = false) {

  def tokenize(value: Any): Token = {
    val jsonStr = toJsonString(value, if (pretty) 0 else -1)
    Token(jsonStr, TokenType.Structured, Map("json" -> true))
  }

  /** Extract and tokenize a value at a dot-separated JSON path. */
  def tokenizePath(value: Any, path: String): Option[Token] = {
    val parts = path.split("\\.")
    var current: Any = value

    for (part <- parts) {
      current match {
        case m: Map[_, _] =>
          m.asInstanceOf[Map[String, Any]].get(part) match {
            case Some(v) => current = v
            case None    => return None
          }
        case l: List[_] if part.forall(_.isDigit) =>
          val idx = part.toInt
          if (idx >= 0 && idx < l.size) current = l(idx)
          else return None
        case _ => return None
      }
    }

    Some(tokenize(current))
  }

  private def toJsonString(value: Any, indent: Int): String = {
    val nextIndent = if (indent >= 0) indent + 2 else -1
    val isPretty = indent >= 0

    value match {
      case null         => "null"
      case s: String    => "\"" + escapeJson(s) + "\""
      case b: Boolean   => b.toString
      case i: Int       => i.toString
      case l: Long      => l.toString
      case f: Float     => f.toString
      case d: Double    => d.toString
      case bd: BigDecimal => bd.toString
      case list: List[_] =>
        if (list.isEmpty) "[]"
        else {
          val items = list.map(toJsonString(_, nextIndent))
          if (isPretty) {
            val pad = " " * nextIndent
            val endPad = " " * indent
            items.mkString(s"[\n$pad", s",\n$pad", s"\n${endPad}]")
          } else items.mkString("[", ", ", "]")
        }
      case m: Map[_, _] =>
        val map = m.asInstanceOf[Map[String, Any]]
        if (map.isEmpty) "{}"
        else {
          val entries = map.toList.map { case (k, v) =>
            val key = "\"" + escapeJson(k.toString) + "\""
            val valStr = toJsonString(v, nextIndent)
            s"$key: $valStr"
          }
          if (isPretty) {
            val pad = " " * nextIndent
            val endPad = " " * indent
            entries.mkString(s"{\n$pad", s",\n$pad", s"\n${endPad}}")
          } else entries.mkString("{", ", ", "}")
        }
      case other => "\"" + escapeJson(other.toString) + "\""
    }
  }

  private def escapeJson(s: String): String =
    s.replace("\\", "\\\\")
      .replace("\"", "\\\"")
      .replace("\n", "\\n")
      .replace("\r", "\\r")
      .replace("\t", "\\t")
}

// ============================================================================
// Whitespace Tokenizer — Basic Text Tokenization
// ============================================================================

/**
 * Basic tokenizer that splits text by whitespace.
 *
 * A fundamental tokenization operation used in NLP and text processing.
 */
class WhitespaceTokenizer(
  lowercase: Boolean = false,
  minLength: Int = 0,
  maxLength: Option[Int] = None,
  stripPunctuation: Boolean = false
) {
  private val punctuation: Set[Char] =
    Set('.', ',', '!', '?', ';', ':', '\'', '"', '(', ')', '[', ']', '{', '}')

  private def processToken(word: String): Option[String] = {
    var w = word

    if (stripPunctuation)
      w = w.dropWhile(punctuation.contains).reverse.dropWhile(punctuation.contains).reverse

    if (lowercase)
      w = w.toLowerCase

    if (w.length < minLength)
      return None

    maxLength.foreach { max =>
      if (w.length > max) w = w.take(max)
    }

    if (w.nonEmpty) Some(w) else None
  }

  /** Split text by whitespace and return list of tokens. */
  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+").filter(_.nonEmpty)

    words.zipWithIndex.flatMap { case (word, i) =>
      processToken(word).map { processed =>
        Token(
          value = processed,
          tokenType = TokenType.String,
          metadata = Map("position" -> i, "original" -> word)
        )
      }
    }.toList
  }

  /** Split text by whitespace and return list of token strings. */
  def tokenizeToStrings(text: String): List[String] =
    tokenize(text).map(_.value)

  /** Tokenize text and return tokens with character positions. */
  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val result = mutable.ListBuffer.empty[(String, Int, Int)]
    var currentPos = 0

    for (word <- text.split("\\s+").filter(_.nonEmpty)) {
      val start = text.indexOf(word, currentPos)
      val end = start + word.length

      processToken(word).foreach { processed =>
        result += ((processed, start, end))
      }

      currentPos = end
    }

    result.toList
  }

  /** Return the number of tokens in the text. */
  def countTokens(text: String): Int = tokenize(text).size
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

/**
 * Fluent builder for creating tokenizers.
 *
 * Uses `this.type` for method chaining with proper return types.
 */
class TokenizerBuilder[T] {
  private val _normalizers = mutable.ListBuffer.empty[String => String]
  private val _validators = mutable.ListBuffer.empty[T => Boolean]
  private var _metadata = Map.empty[String, Any]

  def withNormalizer(normalizer: String => String): this.type = {
    _normalizers += normalizer
    this
  }

  def withValidator(validator: T => Boolean): this.type = {
    _validators += validator
    this
  }

  def withMetadata(entries: (String, Any)*): this.type = {
    _metadata = _metadata ++ entries.toMap
    this
  }

  /** Build the final tokenizer function. */
  def build(): T => Token = {
    val normalizers = _normalizers.toList
    val validators = _validators.toList
    val metadata = _metadata

    value => {
      validators.foreach { validator =>
        if (!validator(value))
          throw new IllegalArgumentException(s"Validation failed for $value")
      }

      var strValue = value.toString

      normalizers.foreach { normalizer =>
        strValue = normalizer(strValue)
      }

      Token(strValue, TokenType.String, metadata)
    }
  }
}

// ============================================================================
// Companion Object — Module-Level Functions
// ============================================================================

object Tokenizer {

  /** Convenience function: tokenize any value using the UniversalTokenizer. */
  def tokenize(value: Any): Token =
    new UniversalTokenizer().tokenize(value)

  /** Convenience function: tokenize a batch of values. */
  def tokenizeBatch(values: Iterable[Any]): Iterator[Token] = {
    val tokenizer = new UniversalTokenizer()
    values.iterator.map(tokenizer.tokenize)
  }

  /** Convert a Tokenizable value to a Token via type class. */
  def toToken[A](value: A)(implicit ev: Tokenizable[A]): Token =
    Token(ev.toToken(value), TokenType.Structured)
}

