// ============================================================================

/** Type class for objects that can be converted to a token string. */
trait Tokenizable[A] {
  def toToken(a: A): String
}

/** Type class for objects with a measurable length. */
trait HasLength[A] {
  def length(a: A): Int
}

/** Contravariant processor that consumes tokens. */
trait TokenProcessor[-A] {
  def process(item: A): Unit
}

// ============================================================================
// Enums and Constants
// ============================================================================

sealed trait TokenType {
  def value: String
}

object TokenType {
  case object String extends TokenType { val value = "string" }
  case object Numeric extends TokenType { val value = "numeric" }
  case object Temporal extends TokenType { val value = "temporal" }
  case object Structured extends TokenType { val value = "structured" }
  case object Binary extends TokenType { val value = "binary" }
  case object Null extends TokenType { val value = "null" }
}

// ============================================================================
// Core Token Classes
// ============================================================================

/** Immutable token representation. */
case class Token(
  value: String,
  tokenType: TokenType,
  metadata: Map[String, Any] = Map.empty
) {

  /** Return new token with additional metadata. */
  def withMetadata(entries: (String, Any)*): Token =
    copy(metadata = metadata ++ entries.toMap)
}

/** Mutable batch of tokens — contrast with immutable Token. */
class MutableTokenBatch {
  private val _tokens = mutable.ListBuffer.empty[Token]
  private var _processed = false

  def add(token: Token): Unit = {
    if (_processed) throw new RuntimeException("Batch already processed")
    _tokens += token
  }

  def tokens: List[Token] = _tokens.toList

  def markProcessed(): Unit = { _processed = true }
}

// ============================================================================
// Generic Container Classes
// ============================================================================

/** Covariant container — can return subtypes. */
class TokenContainer[+A](items: Seq[A]) {
  private val _items: Vector[A] = items.toVector

  def getAll: Vector[A] = _items

  def mapTokens(f: A => String): List[String] = _items.map(f).toList
}

/** Contravariant sink — can accept supertypes. */
class TokenSink[-A] {
  private val _received = mutable.ListBuffer.empty[Any]

  def receive(item: A): Unit = _received += item

  def drain(): List[Any] = {
    val result = _received.toList
    _received.clear()
    result
  }
}

/** Invariant handler — exact type matching required. */
class BivariantHandler[A](private var _value: A) {
  def get: A = _value

  def set(value: A): Unit = { _value = value }

  def transform(f: A => A): A = {
    _value = f(_value)
    _value
  }
}

// ============================================================================
// Tokenizer Implementations
// ============================================================================

/** Abstract base tokenizer with generic input type. */
trait BaseTokenizer[T] {
  def tokenize(value: T): Token

  /** Lazy tokenization of multiple values. */
  def tokenizeBatch(values: Iterable[T]): Iterator[Token] =
    values.iterator.map(tokenize)
}

/** Tokenizer for string and byte-array types. */
class StringTokenizer(
  encoding: String = "UTF-8",
  normalizer: String => String = identity
) extends BaseTokenizer[Either[Array[Byte], String]] {

  override def tokenize(value: Either[Array[Byte], String]): Token = {
    val strValue = value match {
      case Left(bytes) => new String(bytes, encoding)
      case Right(str)  => str
    }
    Token(normalizer(strValue), TokenType.String)
  }

  /** Convenience method to tokenize a plain string. */
  def tokenize(value: String): Token =
    tokenize(Right(value))

  /** Convenience method to tokenize raw bytes. */
  def tokenize(value: Array[Byte]): Token =
    tokenize(Left(value))
}

/** Tokenizer for numeric types with precision handling. */
class NumericTokenizer(
  precision: Int = 6,
  formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[Any] {

  override def tokenize(value: Any): Token = value match {
    case bd: BigDecimal =>
      Token(
        s"%.${precision}f".format(bd.bigDecimal),
        TokenType.Numeric,
        Map("original_type" -> "Decimal")
      )
    case d: Double =>
      Token(
        s"%.${precision}f".format(d),
        TokenType.Numeric,
        Map("original_type" -> "float")
      )
    case f: Float =>
      Token(
        s"%.${precision}f".format(f.toDouble),
        TokenType.Numeric,
        Map("original_type" -> "float")
      )
    case i: Int =>
      Token(i.toString, TokenType.Numeric, Map("original_type" -> "int"))
    case l: Long =>
      Token(l.toString, TokenType.Numeric, Map("original_type" -> "int"))
    case other =>
      Token(other.toString, TokenType.Numeric, Map("original_type" -> other.getClass.getSimpleName))
  }
}

/** Tokenizer for date/time types. */
class TemporalTokenizer(formatStr: Option[String] = None)
  extends BaseTokenizer[Either[LocalDate, LocalDateTime]] {

  private val IsoFormat = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
  private val DateFormat = DateTimeFormatter.ofPattern("yyyy-MM-dd")

  override def tokenize(value: Either[LocalDate, LocalDateTime]): Token = {
    val fmt = formatStr.map(DateTimeFormatter.ofPattern).getOrElse {
      value match {
        case Right(_) => IsoFormat
        case Left(_)  => DateFormat
      }
    }

    val formatted = value match {
      case Right(dt)  => dt.format(fmt)
      case Left(date) => date.format(fmt)
    }

    Token(formatted, TokenType.Temporal)
  }

  /** Convenience method to tokenize a LocalDateTime. */
  def tokenize(value: LocalDateTime): Token =
    tokenize(Right(value))

  /** Convenience method to tokenize a LocalDate. */
  def tokenize(value: LocalDate): Token =
    tokenize(Left(value))
}

