/** Functor for tokens. */
class TokenFunctor[A](protected val _value: A) {
  def map[B](f: A => B): TokenFunctor[B] = new TokenFunctor(f(_value))

  def flatMap[B](f: A => TokenFunctor[B]): TokenFunctor[B] = f(_value)

  def getOrElse(default: => A): A =
    if (_value != null) _value else default
}

/** Extended monad operations. */
class TokenMonad[A](value: A) extends TokenFunctor[A](value) {
  /** Applicative apply. */
  def ap[B](funcWrapped: TokenMonad[A => B]): TokenMonad[B] =
    new TokenMonad(funcWrapped._value(_value))
}

object TokenMonad {
  def pure[A](value: A): TokenMonad[A] = new TokenMonad(value)
}

// ============================================================================
// JSON Structure Tokenization
// ============================================================================

/**
 * Tokenizer for JSON structures with recursive types.
 *
 * Uses Any to model the recursive JSON value type, with pattern matching
 * for type-safe access.
 */
class JsonTokenizer(pretty: Boolean = false) {

  def tokenize(value: Any): Token = {
    val jsonStr = toJsonString(value, if (pretty) 0 else -1)
    Token(jsonStr, TokenType.Structured, Map("json" -> true))
  }

  /** Extract and tokenize a value at a dot-separated JSON path. */
  def tokenizePath(value: Any, path: String): Option[Token] = {
    val parts = path.split("\\.")
    var current: Any = value

    for (part <- parts) {
      current match {
        case m: Map[_, _] =>
          m.asInstanceOf[Map[String, Any]].get(part) match {
            case Some(v) => current = v
            case None    => return None
          }
        case l: List[_] if part.forall(_.isDigit) =>
          val idx = part.toInt
          if (idx >= 0 && idx < l.size) current = l(idx)
          else return None
        case _ => return None
      }
    }

    Some(tokenize(current))
  }

  private def toJsonString(value: Any, indent: Int): String = {
    val nextIndent = if (indent >= 0) indent + 2 else -1
    val isPretty = indent >= 0

    value match {
      case null         => "null"
      case s: String    => "\"" + escapeJson(s) + "\""
      case b: Boolean   => b.toString
      case i: Int       => i.toString
      case l: Long      => l.toString
      case f: Float     => f.toString
      case d: Double    => d.toString
      case bd: BigDecimal => bd.toString
      case list: List[_] =>
        if (list.isEmpty) "[]"
        else {
          val items = list.map(toJsonString(_, nextIndent))
          if (isPretty) {
            val pad = " " * nextIndent
            val endPad = " " * indent
            items.mkString(s"[\n$pad", s",\n$pad", s"\n${endPad}]")
          } else items.mkString("[", ", ", "]")
        }
      case m: Map[_, _] =>
        val map = m.asInstanceOf[Map[String, Any]]
        if (map.isEmpty) "{}"
        else {
          val entries = map.toList.map { case (k, v) =>
            val key = "\"" + escapeJson(k.toString) + "\""
            val valStr = toJsonString(v, nextIndent)
            s"$key: $valStr"
          }
          if (isPretty) {
            val pad = " " * nextIndent
            val endPad = " " * indent
            entries.mkString(s"{\n$pad", s",\n$pad", s"\n${endPad}}")
          } else entries.mkString("{", ", ", "}")
        }
      case other => "\"" + escapeJson(other.toString) + "\""
    }
  }

  private def escapeJson(s: String): String =
    s.replace("\\", "\\\\")
      .replace("\"", "\\\"")
      .replace("\n", "\\n")
      .replace("\r", "\\r")
      .replace("\t", "\\t")
}

// ============================================================================
// Whitespace Tokenizer — Basic Text Tokenization
// ============================================================================

/**
 * Basic tokenizer that splits text by whitespace.
 *
 * A fundamental tokenization operation used in NLP and text processing.
 */
class WhitespaceTokenizer(
  lowercase: Boolean = false,
  minLength: Int = 0,
  maxLength: Option[Int] = None,
  stripPunctuation: Boolean = false
) {
  private val punctuation: Set[Char] =
    Set('.', ',', '!', '?', ';', ':', '\'', '"', '(', ')', '[', ']', '{', '}')

  private def processToken(word: String): Option[String] = {
    var w = word

    if (stripPunctuation)
      w = w.dropWhile(punctuation.contains).reverse.dropWhile(punctuation.contains).reverse

    if (lowercase)
      w = w.toLowerCase

    if (w.length < minLength)
      return None

    maxLength.foreach { max =>
      if (w.length > max) w = w.take(max)
    }

    if (w.nonEmpty) Some(w) else None
  }

  /** Split text by whitespace and return list of tokens. */
  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+").filter(_.nonEmpty)

    words.zipWithIndex.flatMap { case (word, i) =>
      processToken(word).map { processed =>
        Token(
          value = processed,
          tokenType = TokenType.String,
          metadata = Map("position" -> i, "original" -> word)
        )
      }
    }.toList
  }

  /** Split text by whitespace and return list of token strings. */
  def tokenizeToStrings(text: String): List[String] =
    tokenize(text).map(_.value)

  /** Tokenize text and return tokens with character positions. */
  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val result = mutable.ListBuffer.empty[(String, Int, Int)]
    var currentPos = 0

    for (word <- text.split("\\s+").filter(_.nonEmpty)) {
      val start = text.indexOf(word, currentPos)
      val end = start + word.length

      processToken(word).foreach { processed =>
        result += ((processed, start, end))
      }

      currentPos = end
    }

    result.toList
  }

  /** Return the number of tokens in the text. */
  def countTokens(text: String): Int = tokenize(text).size
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

/**
 * Fluent builder for creating tokenizers.
 *
 * Uses `this.type` for method chaining with proper return types.
 */
class TokenizerBuilder[T] {
  private val _normalizers = mutable.ListBuffer.empty[String => String]
  private val _validators = mutable.ListBuffer.empty[T => Boolean]
  private var _metadata = Map.empty[String, Any]

  def withNormalizer(normalizer: String => String): this.type = {
    _normalizers += normalizer
    this
  }

  def withValidator(validator: T => Boolean): this.type = {
    _validators += validator
    this
  }

  def withMetadata(entries: (String, Any)*): this.type = {
    _metadata = _metadata ++ entries.toMap
    this
  }

  /** Build the final tokenizer function. */
  def build(): T => Token = {
    val normalizers = _normalizers.toList
    val validators = _validators.toList
    val metadata = _metadata

    value => {
      validators.foreach { validator =>
        if (!validator(value))
          throw new IllegalArgumentException(s"Validation failed for $value")
      }

      var strValue = value.toString

      normalizers.foreach { normalizer =>
        strValue = normalizer(strValue)
      }

      Token(strValue, TokenType.String, metadata)
    }
  }
}

